const $=id=>document.getElementById(id);let jobs=[],currentJob=null,firebaseAuth=null,authReady=false,toastTimer=null,capabilities={analyze:true,generate:false,repair:false};
const names={dashboard:'Overview','new-analysis':'New scan',workspace:'Repository scan workspace',review:'Code diff & review',tests:'Test results',history:'Scan history',settings:'Settings'};
const protectedPages=new Set(['dashboard','new-analysis','workspace','review','tests','history','settings']);
const isSignedIn=()=>firebaseAuth?!!firebaseAuth.currentUser:sessionStorage.getItem('repofix_signed_in')==='1';
function finishSignIn(){sessionStorage.setItem('repofix_signed_in','1');sessionStorage.setItem('repofix_welcome_pending','1');syncAccountUI();syncLandingAccount();setTimeout(()=>{go('/');const profile=accountProfile();toast(`Welcome back, ${profile.name}. You’re signed in.`);sessionStorage.removeItem('repofix_welcome_pending')},180)}
function accountProfile(){const user=firebaseAuth?.currentUser,email=user?.email||'Signed in',emailName=email.includes('@')?email.split('@')[0]:'',name=user?.displayName||emailName||'RepoFix user',initials=(name.trim()[0]||emailName[0]||'R').toUpperCase();return{email,name,initials,photo:''}}
function syncLandingAccount(){const actions=document.querySelector('.landing-nav .nav-actions');if(!actions)return;const signedIn=isSignedIn(),profile=accountProfile(),guestIcon='<svg aria-hidden="true" viewBox="0 0 24 24"><circle cx="12" cy="8" r="3.2"/><path d="M5.5 20v-2.2c0-3 2.5-5.3 5.5-5.3h2c3 0 5.5 2.3 5.5 5.3V20"/></svg>';actions.innerHTML=signedIn?`<a class="button dark landing-workspace" href="/dashboard" data-link>Open workspace <span>→</span></a><div class="landing-account"><button type="button" data-landing-account aria-label="Open profile" aria-expanded="false"><span>${esc(profile.initials)}</span></button><div class="landing-account-menu" hidden><b>${esc(profile.name)}</b><small>${esc(profile.email)}</small><a href="/dashboard" data-link>Go to workspace</a><a href="/logout">Log out</a></div></div>`:`<div class="landing-account guest-account"><button type="button" data-landing-account aria-label="Open guest menu" aria-expanded="false"><span>${guestIcon}</span></button><div class="landing-account-menu guest-menu" hidden><b>Guest</b><small>Sign in to access your workspace</small><a class="guest-login" href="/login" data-link>↪ &nbsp; Log in</a><a class="guest-signup" href="/login?signup=1">Sign up free</a></div></div>`;if(signedIn)document.querySelectorAll('#landing a[href="/login"]').forEach(link=>{link.href='/dashboard';link.textContent='Open workspace →'});const button=actions.querySelector('[data-landing-account]'),menu=actions.querySelector('.landing-account-menu');button.addEventListener('click',event=>{event.stopPropagation();menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',String(!menu.hidden))});document.addEventListener('click',event=>{if(!event.target.closest('.landing-account')){menu.hidden=true;button.setAttribute('aria-expanded','false')}},{once:true})}
function installNativeLogout(){const dropdown=document.querySelector('[data-account-dropdown]');if(dropdown&&!dropdown.querySelector('.native-logout')){dropdown.querySelector('[data-account-signout]')?.remove();const link=document.createElement('a');link.className='native-logout';link.href='/logout';link.textContent='Log out';dropdown.appendChild(link)}const sidebarLogout=document.querySelector('.sidebar-user [data-signout]');if(sidebarLogout){const link=document.createElement('a');link.className='sidebar-native-logout';link.href='/logout';link.textContent='Log out';sidebarLogout.replaceWith(link)}}
function ensureAccountMenu(){const actions=document.querySelector('.header-actions');if(!actions)return;actions.querySelector(':scope > .button.primary')?.remove();if(!actions.querySelector('.account-menu'))actions.insertAdjacentHTML('beforeend','<div class="account-menu"><button class="account-trigger" type="button" data-account-trigger aria-label="Open account menu" aria-expanded="false"><span class="account-avatar" data-user-avatar>RF</span></button><div class="account-dropdown" data-account-dropdown hidden><div class="account-summary"><span class="account-avatar large" data-user-avatar>RF</span><span><b data-user-name>RepoFix user</b><small data-user-email>Signed in</small></span></div><button type="button" data-account-signout>Log out</button></div></div>');const logout=actions.querySelector('[data-account-signout]');if(logout&&!logout.dataset.bound){logout.dataset.bound='1';logout.addEventListener('click',async event=>{event.preventDefault();event.stopPropagation();logout.disabled=true;logout.textContent='Logging out…';try{await firebaseAuth?.signOut()}finally{sessionStorage.removeItem('repofix_signed_in');sessionStorage.removeItem('repofix_welcome_pending');history.replaceState({page:'/login'},'','/login');await render();setTimeout(()=>toast('Logged out successfully.'),80)}})}}
function syncAccountUI(){ensureAccountMenu();const profile=accountProfile();document.querySelectorAll('[data-user-name]').forEach(node=>node.textContent=profile.name);document.querySelectorAll('[data-user-email]').forEach(node=>node.textContent=profile.email);document.querySelectorAll('[data-user-avatar]').forEach(node=>{node.textContent=profile.photo?'':profile.initials;node.style.backgroundImage=profile.photo?`url("${profile.photo.replace(/"/g,'')}")`:'';node.classList.toggle('has-photo',!!profile.photo)});const sidebar=document.querySelector('.sidebar-user');if(sidebar){sidebar.querySelector('b').textContent=profile.name;sidebar.querySelector('small').textContent=profile.email}}
async function initializeAuthentication(){try{const response=await fetch('/api/auth/config',{signal:AbortSignal.timeout(4000)}),settings=await response.json();if(settings.enabled&&window.firebase){firebase.initializeApp(settings.config);firebaseAuth=firebase.auth();await new Promise(resolve=>firebaseAuth.onAuthStateChanged(()=>resolve(),()=>resolve()))}}catch{}authReady=true}
function completeSignIn(){sessionStorage.setItem('repofix_signed_in','1');toast('Signed in. Opening your workspace…');setTimeout(()=>go('/dashboard'),350)}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
async function api(path,options={}){const headers=new Headers(options.headers||{});let user=firebaseAuth?.currentUser;if(user)headers.set('Authorization',`Bearer ${await user.getIdToken()}`);let response=await fetch(path,{...options,headers});if(response.status===401&&(user=firebaseAuth?.currentUser)){headers.set('Authorization',`Bearer ${await user.getIdToken(true)}`);response=await fetch(path,{...options,headers})}let data={};try{data=await response.json()}catch{}if(response.status===401){await firebaseAuth?.signOut();sessionStorage.removeItem('repofix_signed_in');sessionStorage.removeItem('repofix_welcome_pending');go('/login');setTimeout(()=>toast('Your session could not be verified. Please sign in again.'),100)}if(!response.ok)throw new Error(data.detail||`Request failed (${response.status})`);return data}
function route(){return location.pathname.replace(/^\//,'')||'landing'}
function go(path,{replace=false}={}){if(`${location.pathname}${location.search}`===path)return;history[replace?'replaceState':'pushState']({page:path},'',path);render()}
document.addEventListener('click',event=>{const link=event.target.closest('[data-link]');if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();if(link.dataset.jobId)currentJob=jobs.find(job=>String(job.id)===link.dataset.jobId)||currentJob;const path=link.getAttribute('href');go(path,{replace:path==='/'||path==='/dashboard'})});
window.addEventListener('popstate',()=>render());
document.addEventListener('click',async event=>{const logout=event.target.closest('[data-account-signout]');if(!logout)return;event.preventDefault();event.stopImmediatePropagation();logout.disabled=true;logout.textContent='Logging out…';try{if(firebaseAuth)await firebaseAuth.signOut()}catch(error){console.error('Firebase sign-out failed',error)}sessionStorage.removeItem('repofix_signed_in');sessionStorage.removeItem('repofix_welcome_pending');location.replace('/?logged_out=1')},true);
document.addEventListener('click',async event=>{const trigger=event.target.closest('[data-account-trigger]'),menu=document.querySelector('[data-account-dropdown]');if(trigger&&menu){const opening=menu.hidden;menu.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening));return}if(event.target.closest('[data-account-signout]')){await firebaseAuth?.signOut();sessionStorage.removeItem('repofix_signed_in');menu.hidden=true;go('/');return}if(menu&&!menu.hidden&&!event.target.closest('.account-menu')){menu.hidden=true;document.querySelector('[data-account-trigger]')?.setAttribute('aria-expanded','false')}});
document.querySelector('.header-actions')?.insertAdjacentHTML('afterbegin','<a class="button home-button small" href="/" data-link>⌂ Home</a>');
