if(landingBrandMark){const logo=document.createElement('img');logo.className='brand-logo';logo.src='/static/repofix-logo-v2.png';logo.alt='RepoFix logo';landingBrandMark.replaceWith(logo)}
const sidebarUser=document.querySelector('.sidebar-user');if(sidebarUser){sidebarUser.querySelector('.avatar').textContent='RF';sidebarUser.querySelector('b').textContent='RepoFix';sidebarUser.querySelector('small').textContent='Local engineering workspace';sidebarUser.querySelector('button').textContent='Sign out'}
const historyNav=document.querySelector('[data-page="history"]');if(historyNav)historyNav.innerHTML='<span>↺</span>Analysis history';
const workspaceNav=document.querySelector('[data-page="workspace"]');if(workspaceNav)workspaceNav.innerHTML='<span>✦</span>Scan workspace <em>1</em>';
function badge(status='queued'){return `<span class="badge ${esc(status)}">${esc(status)}</span>`}
const sampleJobs=[{id:1842,repository:'acme/payments-api',status:'running',created_at:new Date(Date.now()-120000),result:{language:'Python',framework:'FastAPI'}},{id:1841,repository:'orbit/web-console',status:'completed',created_at:new Date(Date.now()-3600000),result:{language:'TypeScript',framework:'Next.js'}},{id:1839,repository:'northstar/identity',status:'completed',created_at:new Date(Date.now()-86400000),result:{language:'Java',framework:'Spring'}}];
function displayJobs(){return jobs}
async function loadData(){try{jobs=await api('/api/jobs');if(currentJob)currentJob=jobs.find(job=>job.id===currentJob.id)||currentJob}catch{}try{const h=await api('/api/health'),queue=h.queue||{},ok=queue.available;$('sideHealth')?.classList.toggle('online',!!ok);if($('queueHealth'))$('queueHealth').textContent=ok?(queue.backend==='local'?'Local worker ready':`${queue.queued||0} queued · Redis connected`):'Queue unavailable'}catch{if($('queueHealth'))$('queueHealth').textContent='API available · queue offline'} }
async function initializeCapabilities(){try{const response=await fetch('/api/health'),health=await response.json();capabilities={...capabilities,...(health.capabilities||{})}}catch{}}
function title(name,desc,action=''){return `<header class="page-title"><div><span class="eyebrow-app">ENGINEERING CONSOLE</span><h1>${name}</h1><p>${desc}</p></div>${action}</header>`}
function dashboard(){
  const list=displayJobs();
  const completed=list.filter(job=>job.status==='completed').length;
  const active=list.filter(job=>['queued','running'].includes(job.status)).length;
  const patches=list.filter(job=>Boolean(job.result?.patch)).length;
  const attention=list.filter(job=>job.status==='failed').length;
  const metrics=[
    ['Total analyses',list.length,'Across your repositories'],
    ['Completed',completed,'Scans and repair workflows'],
    ['Patches ready',patches,'Available for review'],
    ['Needs attention',attention,'Failed or interrupted runs'],
  ];
  const activity=list.length?list.slice(0,5).map(job=>`<div class="activity"><span class="repo-icon">${String(job.id).slice(-2)}</span><span><b>${esc(job.repository.replace('https://github.com/',''))}</b><small>Analysis #${job.id} ? ${timeAgo(job.created_at)}</small></span>${badge(job.status)}</div>`).join(''):'<div class="dashboard-empty"><b>No analyses yet</b><p>Start with a repository and a clear description of what you want to inspect.</p><a class="button primary small" href="/new-analysis" data-link>Start an analysis</a></div>';
  return `${title('Repository workspace','A clear view of your latest repository activity.','<a class="button primary small" href="/new-analysis" data-link>New analysis</a>')}<section class="stats-grid">${metrics.map(([label,value,note],index)=>`<article class="stat-card"><header><span>${label}</span><span class="stat-index">0${index+1}</span></header><strong>${value}</strong><span class="trend neutral">${note}</span></article>`).join('')}</section><section class="dashboard-grid"><article class="panel"><header class="panel-head"><div><h2>Recent analyses</h2><p>${active?`${active} active ? `:''}Latest repository runs</p></div><a href="/history" data-link class="text-button">View history ?</a></header><div class="panel-body activity-list">${activity}</div></article><aside class="panel quick-card"><span class="eyebrow-app">WORKFLOW</span><h3>From repository to evidence</h3><p>Choose a scan, a generated patch, or a verified repair when you start a run.</p><div class="quick-steps"><div><span>01</span>Connect a public GitHub repository</div><div><span>02</span>Describe the issue or goal</div><div><span>03</span>Review findings and evidence</div></div><a class="text-button" href="/new-analysis" data-link>Configure a run ?</a></aside></section>`
}
function newAnalysis(){return `${title('Start a new analysis','Tell RepoFix what to fix or improve.')}<section class="form-grid"><form id="analysisForm" class="panel form-panel"><div class="field"><label for="repository">GitHub repository URL <span>Public HTTPS repositories</span></label><input id="repository" class="control" type="url" required placeholder="https://github.com/organization/repository"></div><div class="two-fields"><div class="field"><label for="repairMode">Workflow</label><select class="control" id="repairMode"><option value="generate">Generate fix and report</option><option value="repair">Apply fix, run tests, and report</option><option value="analyze">Analyze repository only</option></select></div><div class="field"><label>Execution policy</label><input class="control" value="Isolated workspace" disabled></div></div><div class="field"><label for="issue">What should RepoFix fix or improve? <span id="charCount">0 / 8,000</span></label><textarea id="issue" class="control" required minlength="20" maxlength="8000" placeholder="Describe the problem, expected behavior, reproduction steps, errors, or improvement you want…"></textarea></div><div class="form-actions"><small>AI will inspect relevant code, propose a patch, and generate a report.</small><button class="button primary" id="analyzeButton">Generate fix and report →</button></div></form><aside class="panel tip-card"><span class="eyebrow-app">BEFORE YOU START</span><h3>Get a stronger analysis</h3><div class="tip-list"><div><i>1</i><span><b>Be specific about behavior</b><small>Include what happened and what you expected.</small></span></div><div><i>2</i><span><b>Add reproduction steps</b><small>Reliable reproduction leads to focused fixes.</small></span></div><div><i>3</i><span><b>Request improvements</b><small>Explain the performance, security, UX, or maintainability goal.</small></span></div></div><hr><small>Report includes</small><p>Findings · relevant files · code changes<br>Validation · recommended next steps</p></aside></section>`}
function workspace(){return `${title('AI analysis workspace','Follow the repair agent as it investigates and verifies the issue.',badge('running'))}<section class="timeline-layout"><article class="panel progress-card"><div class="progress-top"><div><span class="eyebrow-app">ANALYSIS #1842</span><h2>acme / payments-api</h2><p>Checkout fails when a customer has no saved currency.</p></div><div class="progress-ring"><span>76%</span></div></div><div class="timeline"><div class="timeline-row done"><i>✓</i><div><b>Repository cloned and mapped</b><small>148 source files indexed · Python / FastAPI detected</small></div><time>00:18</time></div><div class="timeline-row done"><i>✓</i><div><b>Issue context understood</b><small>Matched issue terms across 12 candidate files</small></div><time>00:43</time></div><div class="timeline-row done"><i>✓</i><div><b>Root cause isolated</b><small>Missing fallback for nullable currency at src/checkout.py:84</small></div><time>01:26</time></div><div class="timeline-row active"><i>✦</i><div><b>Generating and validating patch</b><small>Checking call sites and updating regression coverage…</small></div><time>02:14</time></div><div class="timeline-row"><i>5</i><div><b>Run tests in sandbox</b><small>Waiting for patch validation</small></div></div></div></article><aside><article class="panel"><header class="panel-head"><div><h2>Relevant files</h2><p>Ranked by semantic relevance</p></div></header><div class="panel-body files-list"><div class="file-row"><span>src/checkout.py</span><b class="score">96%</b></div><div class="file-row"><span>src/models/customer.py</span><b class="score">82%</b></div><div class="file-row"><span>tests/test_checkout.py</span><b class="score">78%</b></div><div class="file-row"><span>src/currency.py</span><b class="score">61%</b></div></div></article><article class="panel" style="margin-top:14px"><header class="panel-head"><div><h2>Environment</h2><p>Detected automatically</p></div></header><div class="panel-body tip-list"><div><i>Py</i><span><b>Python 3.12</b><small>FastAPI · SQLAlchemy</small></span></div><div><i>✓</i><span><b>Pytest</b><small>142 tests detected</small></span></div><div><i>◇</i><span><b>Docker sandbox</b><small>Network disabled</small></span></div></div></article></aside></section>`}
function review(){const lines=[['',80,80,'def resolve_currency(customer):'],['',81,81,'    currency = customer.currency'],['del',82,'','    return currency.upper()'],['add','',82,'    # Fall back when no preference is saved'],['add','',83,'    currency = currency or DEFAULT_CURRENCY'],['add','',84,'    return currency.upper()'],['',85,85,''],['',86,86,'def build_checkout(customer, items):']];return `${title('Code diff & review','Inspect every proposed change before publication.','<button class="button primary small" data-approve>Approve patch ✓</button>')}<section class="panel"><header class="panel-head"><div><h2>Proposed patch <span class="badge">High confidence</span></h2><p>3 files changed · <span style="color:var(--green)">+18</span> <span style="color:var(--red)">−4</span></p></div><div class="diff-toolbar"><button class="button ghost small" data-diff-view>Toggle line wrap</button><button class="button ghost small" data-review-more>Patch details</button></div></header><div class="diff-wrap"><aside class="file-tabs"><button class="active">M src/checkout.py</button><button>M tests/test_checkout.py</button><button>M src/constants.py</button></aside><div class="diff-code" data-diff-code>${lines.map(l=>`<div class="diff-line ${l[0]}"><span>${l[1]}</span><span>${l[2]}</span><code>${esc(l[3])}</code></div>`).join('')}</div></div></section><section class="panel" style="margin-top:14px"><div class="panel-body"><span class="eyebrow-app">AGENT RATIONALE</span><p style="max-width:850px;font-size:11px">The failure occurs because <code>customer.currency</code> is nullable while the checkout path assumes a string. This patch applies the existing system default before normalization and adds a regression test for customers without a saved preference.</p></div></section>`}
function testsPage(){return `${title('Test results','Verification evidence from the isolated repair sandbox.','<button class="button ghost small" data-rerun>↻ Rerun tests</button>')}<section class="test-summary"><article class="panel big-pass"><div><div class="ring">✓</div><h2>All tests passed</h2><p>142 passed · 0 failed · 2.84s</p>${badge('verified')}</div></article><article class="panel"><header class="panel-head"><div><h2>Test suites</h2><p>Python 3.12 · pytest 8.3</p></div><span class="badge">142 / 142</span></header><table class="test-table"><thead><tr><th>SUITE</th><th>RESULT</th><th>TESTS</th><th>DURATION</th></tr></thead><tbody><tr><td><b>tests/test_checkout.py</b></td><td>${badge('passed')}</td><td>18</td><td>0.44s</td></tr><tr><td><b>tests/test_models.py</b></td><td>${badge('passed')}</td><td>46</td><td>0.71s</td></tr><tr><td><b>tests/test_payments.py</b></td><td>${badge('passed')}</td><td>52</td><td>1.12s</td></tr><tr><td><b>tests/test_api.py</b></td><td>${badge('passed')}</td><td>26</td><td>0.57s</td></tr></tbody></table></article></section><article class="panel" style="margin-top:14px"><header class="panel-head"><div><h2>Sandbox output</h2><p>Offline container · 2 CPU · 512 MB memory</p></div><button class="button ghost small" data-copy>Copy logs</button></header><div class="diff-code" style="padding:18px"><code>============================= test session starts =============================<br>platform linux -- Python 3.12.7, pytest-8.3.3<br>collected 142 items<br><br><span class="terminal-good">tests/test_checkout.py .................. [ 12%]<br>tests/test_models.py .............................................. [ 45%]<br>tests/test_payments.py .................................................... [ 82%]<br>tests/test_api.py .......................... [100%]</span><br><br>============================= 142 passed in 2.84s =============================</code></div></article>`}
function historyPage(){return `${title('Analysis history','Search, filter, and reopen previous repository analyses.')}<section class="panel"><header class="panel-head"><div><h2>All analyses</h2><p>${displayJobs().length} analyses in this workspace</p></div><div class="history-tools"><input id="historySearch" class="control" style="min-height:35px;width:220px" placeholder="Search repositories…"><select id="statusFilter" class="control" style="min-height:35px;width:120px"><option>All statuses</option><option>Completed</option><option>Running</option><option>Failed</option></select></div></header><div style="overflow:auto"><table class="history-table"><thead><tr><th>ANALYSIS</th><th>REPOSITORY</th><th>STATUS</th><th>TECHNOLOGY</th><th>CREATED</th><th></th></tr></thead><tbody id="historyRows">${historyRows(displayJobs())}</tbody></table></div></section>`}
function historyRows(list){return list.map(j=>`<tr><td><b>#${j.id}</b></td><td><code>${esc(j.repository.replace('https://github.com/',''))}</code></td><td>${badge(j.status)}</td><td>${esc(j.result?.language||'Detecting')} · ${esc(j.result?.framework||'—')}</td><td>${timeAgo(j.created_at)}</td><td><a href="/${j.result?.patch?'review':'workspace'}" data-link data-job-id="${j.id}">Open →</a></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No analyses match this filter.</td></tr>'}
const settingsTabs=['General','GitHub connection','Security','Notifications'];
function settingsPanel(tab='General'){const panels={General:`<span class="eyebrow-app">WORKSPACE</span><h2>General preferences</h2><div class="setting-row"><span><b>Workspace name</b><small>Shown across your engineering console</small></span><input class="control" data-setting="workspace" value="${esc(localStorage.getItem('repofix_workspace')||'Engineering workspace')}"></div><div class="setting-row"><span><b>Default base branch</b><small>Used when a repository does not specify one</small></span><select class="control" data-setting="branch"><option>main</option><option>master</option></select></div><div class="setting-row"><span><b>Auto-run detected tests</b><small>Start sandbox verification after generating a valid patch</small></span><button class="toggle on" aria-label="Toggle auto tests"></button></div><div class="setting-row"><span><b>Analysis retention</b><small>Automatically remove isolated workspaces after this period</small></span><select class="control" data-setting="retention"><option>30 days</option><option>7 days</option><option>90 days</option></select></div>`, 'GitHub connection':`<span class="eyebrow-app">SOURCE CONTROL</span><h2>GitHub connection</h2><div class="setting-row"><span><b>Repository access</b><small>Public HTTPS repositories are available</small></span><span class="badge completed">Connected</span></div><button class="button ghost small" data-connect-github>Check connection</button>`, 'AI models':`<span class="eyebrow-app">INTELLIGENCE</span><h2>AI model preferences</h2><div class="setting-row"><span><b>Repair model</b><small>Used for patch generation and reasoning</small></span><select class="control" data-setting="model"><option>gpt-5.1-codex-mini</option><option>gpt-5</option></select></div><div class="setting-row"><span><b>Maximum attempts</b><small>Retries after failed validation</small></span><select class="control" data-setting="attempts"><option>3</option><option>2</option><option>1</option></select></div>`,Security:`<span class="eyebrow-app">PROTECTION</span><h2>Security controls</h2><div class="setting-row"><span><b>Require approval before publication</b><small>Never publish code without explicit approval</small></span><button class="toggle on" aria-label="Toggle publication approval"></button></div><div class="setting-row"><span><b>Isolated execution</b><small>Run verification without outbound networking</small></span><button class="toggle on" aria-label="Toggle isolated execution"></button></div>`,Notifications:`<span class="eyebrow-app">UPDATES</span><h2>Notification preferences</h2><div class="setting-row"><span><b>Workflow completed</b><small>Notify when analysis evidence is ready</small></span><button class="toggle on" aria-label="Toggle workflow notifications"></button></div><div class="setting-row"><span><b>Workflow failed</b><small>Notify when a repair requires attention</small></span><button class="toggle on" aria-label="Toggle failure notifications"></button></div>`};return panels[tab]||panels.General}
function settings(){return `${title('Settings','Manage connections, security, notifications, and workspace defaults.','<button class="button primary small" data-save>Save changes</button>')}<section class="settings-grid"><aside class="panel settings-menu">${settingsTabs.map((tab,index)=>`<button class="${index?'':'active'}" data-settings-tab="${esc(tab)}">${esc(tab)}</button>`).join('')}</aside><article id="settingsContent" class="panel form-panel">${settingsPanel()}</article></section>`}
