const liveConsole=document.querySelector('.workflow-console');
if(liveConsole&&motionAllowed){
  liveConsole.addEventListener('pointermove',event=>{
    const bounds=liveConsole.getBoundingClientRect();
    const x=(event.clientX-bounds.left)/bounds.width-.5;
    const y=(event.clientY-bounds.top)/bounds.height-.5;
    liveConsole.style.setProperty('--tilt-x',`${(-y*3.5).toFixed(2)}deg`);
    liveConsole.style.setProperty('--tilt-y',`${(x*4.5).toFixed(2)}deg`);
    liveConsole.style.setProperty('--lift','-5px');
  });
  liveConsole.addEventListener('pointerleave',()=>{
    liveConsole.style.setProperty('--tilt-x','0deg');
    liveConsole.style.setProperty('--tilt-y','0deg');
    liveConsole.style.setProperty('--lift','0px');
  });
}
const revealTargets=document.querySelectorAll('#workflow .section-heading,.workflow-console,#workflow .feature,.security-inner>div,.security-list>div,.cta>div,.cta>.button');
if('IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
  revealTargets.forEach(element=>element.classList.add('reveal-ready'));
  const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');revealObserver.unobserve(entry.target)}}),{threshold:.16,rootMargin:'0px 0px -55px'});
  revealTargets.forEach(element=>revealObserver.observe(element));
}
